export function fireEnemyWeapon(enemy, playerPos, activeEnemyBolts, scene) {
  if (!enemy || !enemy.mesh || !activeEnemyBolts || !scene) return false;

  const enemyBolts = activeEnemyBolts();
  if (enemyBolts.length > 80) return false;

  const primaryW = (enemy.weapons && enemy.weapons[0]) || {};
  const wScale = Number(enemy.weapon_scale ?? primaryW.scale ?? 1.0);
  const wScaleX = Number(enemy.weapon_scale_x ?? primaryW.scale_x ?? 1.0);
  const wScaleY = Number(enemy.weapon_scale_y ?? primaryW.scale_y ?? 1.0);
  const wScaleZ = Number(enemy.weapon_scale_z ?? primaryW.scale_z ?? 1.0);
  const wSizeX = Number(enemy.weapon_size_x ?? primaryW.size_x ?? (primaryW.dimensions && primaryW.dimensions.x) ?? 1.0);
  const wSizeY = Number(enemy.weapon_size_y ?? primaryW.size_y ?? (primaryW.dimensions && primaryW.dimensions.y) ?? 1.0);
  const wSizeZ = Number(enemy.weapon_size_z ?? primaryW.size_z ?? (primaryW.dimensions && primaryW.dimensions.z) ?? 1.0);

  const wSpecialFx = primaryW.special_fx || enemy.weapon_special_fx || 'cockpit_cracks_red_edges';
  const wSpecialFxFile = primaryW.special_fx_file || enemy.weapon_special_fx_file || 'desktop/warp_origin_images/cockpit_cracks_overlay.png';
  const wSpecialFxType = primaryW.special_fx_type || enemy.weapon_special_fx_type || 'overlay';
  const wColor = enemy.weaponColor || enemy.weapon_color || primaryW.color || '#00f0ff';
  const wName = primaryW.name || enemy.weapon_name || 'Enemy Laser';
  const wId = primaryW.id || enemy.weapon_id || 'enemy_laser';

  let mesh = null;
  let fromPool = false;
  let geometryList = [];
  let materialList = [];

  const target = (playerPos && playerPos.isVector3) ? playerPos : new THREE.Vector3(0, 0, 220);
  const direction = new THREE.Vector3().subVectors(target, enemy.mesh.position).normalize();
  const boltQuat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), direction);

  if (window.stageObjectPool && typeof window.stageObjectPool.spawnEnemyWeapon === 'function') {
    mesh = window.stageObjectPool.spawnEnemyWeapon(primaryW, enemy, enemy.mesh.position, boltQuat, isMissile ? 'missile' : 'beam');
    if (mesh) fromPool = true;
  }

  if (!mesh) {
    const boltGeom = new THREE.CylinderGeometry(0.08 * wSizeX, 0.08 * wSizeY, 1.6 * wSizeZ, 6);
    boltGeom.rotateX(Math.PI / 2);
    const boltMat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(wColor),
      wireframe: false
    });

    mesh = new THREE.Mesh(boltGeom, boltMat);
    mesh.scale.set(wScale * wScaleX, wScale * wScaleY, wScale * wScaleZ);
    mesh.position.copy(enemy.mesh.position);
    mesh.quaternion.copy(boltQuat);

    geometryList = [boltGeom];
    materialList = [boltMat];
    scene.add(mesh);
  } else {
    mesh.position.copy(enemy.mesh.position);
    mesh.quaternion.copy(boltQuat);
  }

  const isMissile = (enemy.weaponType === 'missile' || (enemy.weaponName && enemy.weaponName.toLowerCase().includes('missile')));
  const boltSpeed = enemy.weaponSpeed || enemy.weapon_speed || 420;
  const boltDamage = enemy.weaponDamage || enemy.weapon_damage || 5;

  enemyBolts.push({
    mesh,
    fromPool,
    geometryList,
    materialList,
    direction,
    speed: boltSpeed,
    damage: boltDamage,
    weaponId: wId,
    weaponName: wName,
    weaponColor: wColor,
    specialFx: wSpecialFx,
    specialFxFile: wSpecialFxFile,
    specialFxType: wSpecialFxType,
    scale: wScale,
    scale_x: wScaleX,
    scale_y: wScaleY,
    scale_z: wScaleZ,
    size_x: wSizeX,
    size_y: wSizeY,
    size_z: wSizeZ,
    dimensions: { x: wSizeX, y: wSizeY, z: wSizeZ },
    type: isMissile ? 'missile' : 'beam',
    spiralTime: Math.random() * Math.PI * 2,
    spawnTime: performance.now(),
    lifetime: 4.8
  });

  return true;
}

export function updateEnemyMovement(enemy, delta, playerPos, scene) {
  if (!enemy || !enemy.mesh) return;
  // Default forward intercept trajectory
  if (typeof enemy.speed === 'number' && enemy.speed > 0) {
    const dir = new THREE.Vector3().subVectors(playerPos, enemy.mesh.position).normalize();
    enemy.mesh.position.addScaledVector(dir, enemy.speed * delta * 0.1);
  }
}

export function updateStageWaves(pool, activeEnemies, stageKills, scene) {
  if (!pool) return;
  // Waves boilerplate handler
  if (typeof pool.getPoolStats === 'function') {
    return pool.getPoolStats();
  }
}

// =========================================================================
// COCKPIT OVERLAY & IMPACT DECALS MANAGEMENT
// Model: scene_images/screen_decals_spider_web_overlay_4.glb
// Full-screen overlay dynamically scaled via camera FOV for all device viewports.
// Toggleable decals: burn 01-08 for laser burns, strike 01-08 for missile strikes,
// BrokenSpiderWeb Core (on at 0% shield) and BrokenSpiderWeb Screen (on at 0% health
// for 4 seconds before the game over modal displays). Loaded via stage object pool.
// =========================================================================

let activeCockpitCracksMesh = null;
let activeCockpitCracksPool = null;

function getActiveOverlay() {
  const cam = (typeof window !== 'undefined' && window.camera) ? window.camera : null;
  if (cam) {
    const onCam = cam.getObjectByName('cockpit_overlay_object') || cam.getObjectByName('cockpit_cracks_overlay');
    if (onCam) return onCam;
  }
  if (activeCockpitCracksMesh) return activeCockpitCracksMesh;
  if (activeCockpitCracksPool && activeCockpitCracksPool.cockpitCracksMesh) {
    return activeCockpitCracksPool.cockpitCracksMesh;
  }
  return null;
}

export async function setupCockpitCracksOverlay(camera, pool = null, scene = null) {
  if (!camera) {
    camera = (typeof window !== 'undefined' && window.camera) ? window.camera : null;
  }
  if (!scene) {
    scene = (typeof window !== 'undefined' && window.scene) ? window.scene : null;
  }

  if (pool && typeof pool.getCockpitCracksOverlay === 'function') {
    activeCockpitCracksPool = pool;
    activeCockpitCracksMesh = pool.getCockpitCracksOverlay(camera);
    if (activeCockpitCracksMesh) {
      if (camera && activeCockpitCracksMesh.parent !== camera) {
        camera.add(activeCockpitCracksMesh);
      }
      fitCockpitCracksToCamera(activeCockpitCracksMesh, camera);
      return activeCockpitCracksMesh;
    }
  }

  if (camera) {
    const existing = camera.getObjectByName('cockpit_overlay_object') || camera.getObjectByName('cockpit_cracks_overlay');
    if (existing) {
      activeCockpitCracksMesh = existing;
      fitCockpitCracksToCamera(activeCockpitCracksMesh, camera);
      return activeCockpitCracksMesh;
    }
  }

  try {
    const assetUrl = (stageConfig.cockpit_overlay_object && (stageConfig.cockpit_overlay_object.model_3d_url || stageConfig.cockpit_overlay_object.model_url || stageConfig.cockpit_overlay_object.url))
      || stageConfig.cockpit_overlay_asset
      || (stageConfig.cockpit_overlay && (stageConfig.cockpit_overlay.model_3d_url || stageConfig.cockpit_overlay.model_url))
      || 'scene_images/screen_decals_spider_web_overlay_4.glb'
      || (typeof STAGE_COCKPIT_CRACKS_ASSET_URL !== 'undefined' ? STAGE_COCKPIT_CRACKS_ASSET_URL : '')
      || (typeof COCKPIT_CRACKS_GLB_URL !== 'undefined' ? COCKPIT_CRACKS_GLB_URL : '')
      || 'wormhole0/scene_images/screen_decals_spider_web_overlay_4.glb';

    const loadFn = typeof loadCockpitCracksAsset === 'function' ? loadCockpitCracksAsset : loadCockpitCracksGlbAsset;
    const loadedMesh = await loadFn(assetUrl);
    if (loadedMesh) {
      setupCockpitCracksHierarchy(loadedMesh);

      activeCockpitCracksPool = new MeshPool(
        scene,
        null,
        null,
        1,
        () => {
          const clone = loadedMesh.clone(true);
          setupCockpitCracksHierarchy(clone);
          return clone;
        }
      );

      activeCockpitCracksMesh = activeCockpitCracksPool.spawn();
      setupCockpitCracksHierarchy(activeCockpitCracksMesh);

      if (camera) {
        camera.add(activeCockpitCracksMesh);
        fitCockpitCracksToCamera(activeCockpitCracksMesh, camera);
      }
      console.log(`[Cockpit Overlay] Cockpit screen overlay loaded with pool and mounted across cockpit view`);
    }
  } catch (err) {
    console.warn(`[Cockpit Overlay] Error setting up cockpit overlay:`, err);
  }

  return activeCockpitCracksMesh;
}

export function fitCockpitCracksToCamera(mesh, camera) {
  if (!mesh || !camera) return;
  mesh.position.set(0, 0, -1.0);
  mesh.rotation.set(0, 0, 0);

  const aspect = camera.aspect || (typeof window !== 'undefined' && window.innerHeight > 0 ? window.innerWidth / window.innerHeight : 16 / 9);
  let visibleH = 0;
  let visibleW = 0;

  if (camera.fov) {
    const vFovRad = (camera.fov * Math.PI) / 180;
    visibleH = 2 * Math.tan(vFovRad / 2) * 1.0;
    visibleW = visibleH * aspect;
  } else if (camera.projectionMatrix && camera.projectionMatrix.elements && camera.projectionMatrix.elements[5] > 0) {
    visibleH = 2.0 / camera.projectionMatrix.elements[5];
    visibleW = (camera.projectionMatrix.elements[0] > 0)
      ? (2.0 / camera.projectionMatrix.elements[0])
      : (visibleH * aspect);
  } else {
    const vFovRad = (65 * Math.PI) / 180;
    visibleH = 2 * Math.tan(vFovRad / 2) * 1.0;
    visibleW = visibleH * aspect;
  }

  if (mesh.userData && mesh.userData.is2DOverlay) {
    mesh.scale.set(visibleW, visibleH, 1.0);
  } else {
    // Model bounds for screen_decals_spider_web_overlay_4.glb:
    // Base width: 1.60m, Base height: 0.90m (16:9 widescreen)
    // Scale dynamically using FOV so the overlay completely covers the screen for different devices
    const scale = Math.max(visibleW / 1.60, visibleH / 0.90) * 1.05;
    mesh.scale.set(scale, scale, 1.0);
  }
}

export const fitCockpitOverlayToCamera = fitCockpitCracksToCamera;
export const setupCockpitOverlayHierarchy = setupCockpitCracksHierarchy;

export function triggerCockpitCracksHit(weapon = null, durationMs = 280) {
  let weaponType = 'laser';
  if (typeof weapon === 'string') {
    const s = weapon.toLowerCase();
    if (s.includes('missile') || s.includes('strike') || s.includes('torpedo') || s.includes('rocket')) {
      weaponType = 'missile';
    }
  } else if (weapon && typeof weapon === 'object') {
    const s = (
      weapon.type ||
      weapon.weaponType ||
      weapon.weapon_type ||
      weapon.weaponName ||
      weapon.weapon_name ||
      weapon.name ||
      weapon.id ||
      ''
    ).toLowerCase();
    if (s.includes('missile') || s.includes('strike') || s.includes('torpedo') || s.includes('rocket')) {
      weaponType = 'missile';
    }
  }

  const overlay = getActiveOverlay();
  if (overlay) {
    toggleRandomWeaponDecal(overlay, weaponType);
  } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.triggerWeaponDecal === 'function') {
    activeCockpitCracksPool.triggerWeaponDecal(weaponType);
  }

  if (typeof document !== 'undefined') {
    const redEdges = document.getElementById('cockpit-edges-red');
    if (redEdges) {
      redEdges.style.opacity = '1.0';
      setTimeout(() => {
        redEdges.style.opacity = '0';
      }, durationMs);
    }
  }
}

export function triggerShieldDepletedCockpitCracks() {
  const overlay = getActiveOverlay();
  if (overlay) {
    toggleBrokenCoreDecal(overlay);
  } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.triggerShieldDepletedDecal === 'function') {
    activeCockpitCracksPool.triggerShieldDepletedDecal();
  }
}

export function triggerGameOverCockpitCracks(durationMs = 4000) {
  const overlay = getActiveOverlay();
  if (overlay) {
    toggleGameOverDecals(overlay, durationMs);
  } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.showGameOverCockpitCracks === 'function') {
    activeCockpitCracksPool.showGameOverCockpitCracks(durationMs);
  }
  if (typeof document !== 'undefined') {
    const redEdges = document.getElementById('cockpit-edges-red');
    if (redEdges) {
      redEdges.style.opacity = '1.0';
    }
  }
}

export function hideCockpitCracks() {
  const overlay = getActiveOverlay();
  if (overlay) {
    resetCockpitOverlayDecals(overlay);
  } else if (activeCockpitCracksPool && typeof activeCockpitCracksPool.hideCockpitCracks === 'function') {
    activeCockpitCracksPool.hideCockpitCracks();
  }
  if (typeof document !== 'undefined') {
    const redEdges = document.getElementById('cockpit-edges-red');
    if (redEdges) {
      redEdges.style.opacity = '0';
    }
  }
}

export function getActiveCockpitCracksOverlay() {
  return getActiveOverlay();
}

export function handleStageEvent(eventName, payload, engineApi) {
  console.log(`[Stage 1: Warp Origin] Event received: ${eventName}`, payload);
  if (eventName === 'Warp Horizon Jump Gate Initialized') {
    if (engineApi && typeof engineApi.showToast === 'function') {
      engineApi.showToast('🏆 STAGE 1 OBJECTIVE COMPLETE: Warp Horizon Jump Gate Initialized');
    }
  }
}

export function applyStage(engineApi) {
  if (!engineApi) return stageConfig;
  console.log(`[Stage 1: Warp Origin] Applying Desktop Profile configuration...`);

  if (typeof engineApi.setThemeColors === 'function') {
    engineApi.setThemeColors(stageConfig.visual);
  }
  if (typeof engineApi.setHudStatus === 'function') {
    engineApi.setHudStatus('STAGE 1: WARP ORIGIN [DESKTOP]');
  }
  if (typeof engineApi.setFlightConfig === 'function') {
    engineApi.setFlightConfig(stageConfig.visual.flight);
  }
  if (typeof engineApi.setWeapons === 'function') {
    engineApi.setWeapons(stageConfig.weapons);
  }
  if (typeof engineApi.setEnemies === 'function') {
    engineApi.setEnemies(stageConfig.enemies);
  }
  if (typeof engineApi.setPowerups === 'function' && stageConfig.powerups) {
    engineApi.setPowerups(stageConfig.powerups);
  }
  if (typeof engineApi.setEnvironment === 'function' && stageConfig.environment) {
    engineApi.setEnvironment(stageConfig.environment);
  }
  if (typeof engineApi.setStageObjectives === 'function') {
    engineApi.setStageObjectives(stageConfig.objectives || []);
  }
  if (typeof engineApi.setDeviceControls === 'function') {
    engineApi.setDeviceControls(stageConfig.controls);
  }
  if (typeof engineApi.setEnemyWeaponHandler === 'function') {
    engineApi.setEnemyWeaponHandler(fireEnemyWeapon);
  }
  if (typeof engineApi.showToast === 'function') {
    engineApi.showToast('🚀 STAGE 1: WARP ORIGIN [DESKTOP] LOADED');
  }

    // --- Mount Cockpit Overlay Across Cockpit Window via Pool ---
  const camera = (engineApi && engineApi.camera) || (typeof window !== 'undefined' && window.camera);
  const scene = (engineApi && engineApi.scene) || (typeof window !== 'undefined' && window.scene);
  const pool = (engineApi && typeof engineApi.getObjectPool === 'function' ? engineApi.getObjectPool() : null)
    || (typeof window !== 'undefined' && window.stageObjectPool)
    || null;

  setupCockpitCracksOverlay(camera, pool, scene);

  // Resize and orientation handlers to maintain perfect cockpit fit dynamically scaling overlay with FOV
  if (typeof window !== 'undefined') {
    const onResizeFit = () => {
      const cam = (engineApi && engineApi.camera) || window.camera;
      if (activeCockpitCracksMesh && cam) {
        fitCockpitCracksToCamera(activeCockpitCracksMesh, cam);
      }
    };
    window.addEventListener('resize', onResizeFit);
    window.addEventListener('orientationchange', () => setTimeout(onResizeFit, 200));

    // Hook enemy hit detection:
    if (typeof window.applyDamageToPlayer === 'function' && !window.applyDamageToPlayer._cockpitCracksHooked) {
      const prevDamage = window.applyDamageToPlayer;
      window.applyDamageToPlayer = function(dmg, ...args) {
        const weapon = args[0] || (typeof dmg === 'object' ? dmg : null);
        const shieldBefore = (typeof window.state !== 'undefined' && window.state) ? window.state.playerShield : 100;

        const ret = prevDamage.apply(this, [dmg, ...args]);

        const shieldAfter = (typeof window.state !== 'undefined' && window.state) ? window.state.playerShield : 0;
        const healthAfter = (typeof window.state !== 'undefined' && window.state) ? window.state.playerHealth : 100;

        // When hit, detect weapon type and toggle random decal for weapon
        triggerCockpitCracksHit(weapon);

        // When shield reaches 0%, BrokenSpiderWeb Core decal turns on
        if (shieldBefore > 0 && shieldAfter <= 0) {
          triggerShieldDepletedCockpitCracks();
        }

        // When health reaches 0%, both BrokenSpiderWeb Core and BrokenSpiderWeb Screen decals turn on for 4 seconds
        if (healthAfter <= 0) {
          triggerGameOverCockpitCracks(4000);
        }

        return ret;
      };
      window.applyDamageToPlayer._cockpitCracksHooked = true;
    }

    window.addEventListener('cockpitHit', (e) => triggerCockpitCracksHit(e.detail));
    window.addEventListener('playerDamage', (e) => triggerCockpitCracksHit(e.detail));
    window.addEventListener('cockpitImpact', (e) => triggerCockpitCracksHit(e.detail));
    window.addEventListener('shieldDepleted', () => triggerShieldDepletedCockpitCracks());
    window.addEventListener('gameOverCracks', () => triggerGameOverCockpitCracks(4000));

    const prevCustomFx = window.executeCustomWeaponImpactFx;
    window.executeCustomWeaponImpactFx = function(bolt, normX, normY, canvas) {
      if (typeof prevCustomFx === 'function') {
        try { prevCustomFx(bolt, normX, normY, canvas); } catch (e) {}
      }
      triggerCockpitCracksHit(bolt);
    };

    window.triggerCockpitCracksHit = triggerCockpitCracksHit;
    window.triggerCockpitOverlayHit = triggerCockpitCracksHit;
    window.flashCockpitCracks = triggerCockpitCracksHit;
    window.triggerShieldDepletedCockpitCracks = triggerShieldDepletedCockpitCracks;
    window.triggerGameOverCockpitCracks = triggerGameOverCockpitCracks;
    window.hideCockpitCracks = hideCockpitCracks;
    window.resetCockpitOverlayDecals = resetCockpitOverlayDecals;
    window.setupCockpitCracksOverlay = setupCockpitCracksOverlay;
    window.setupCockpitOverlayHierarchy = setupCockpitCracksHierarchy;
    window.fitCockpitCracksToCamera = fitCockpitCracksToCamera;
    window.fitCockpitOverlayToCamera = fitCockpitCracksToCamera;
    window.getActiveCockpitCracksOverlay = getActiveCockpitCracksOverlay;
  }

  return stageConfig;
}

export default {
  stageConfig,
  applyStage,
  fireEnemyWeapon,
  updateEnemyMovement,
  updateStageWaves,
  handleStageEvent,
  stageEvents,
  setupCockpitCracksOverlay,
  setupCockpitOverlayHierarchy,
  triggerCockpitCracksHit,
  triggerShieldDepletedCockpitCracks,
  triggerGameOverCockpitCracks,
  hideCockpitCracks,
  fitCockpitCracksToCamera,
  fitCockpitOverlayToCamera,
  getActiveCockpitCracksOverlay
};